@page "/"

<PageTitle>ShipmentTracker — Track Your Shipment</PageTitle>

<div class="text-center my-5">
    <h1>📦 ShipmentTracker</h1>
    <p class="lead">Track your shipment in real time</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="input-group input-group-lg">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. ST-100001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                Track
            </button>
        </div>

        @if (isLoading)
        {
            <div class="text-center mt-4">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Searching…</span>
                </div>
            </div>
        }
        else if (searched && shipment is null)
        {
            <div class="alert alert-warning mt-4">
                No shipment found for tracking number <strong>@searchedNumber</strong>.
            </div>
        }
        else if (shipment is not null)
        {
            <div class="card mt-4">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@shipment.TrackingNumber</strong>
                    <span class="badge @StatusBadgeClass(shipment.Status)">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>

                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>

                        <dt class="col-sm-5">Recipient</dt>
                        <dd class="col-sm-7">@shipment.RecipientName</dd>

                        <dt class="col-sm-5">Description</dt>
                        <dd class="col-sm-7">@shipment.Description</dd>

                        <dt class="col-sm-5">Shipped</dt>
                        <dd class="col-sm-7">@shipment.CreatedDate.ToString("MMM dd, yyyy")</dd>

                        <dt class="col-sm-5">Estimated Delivery</dt>
                        <dd class="col-sm-7">
                            @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")
                        </dd>
                    </dl>
                </div>
            </div>
        }
    </div>
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool isLoading;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        searched = false;
        shipment = null;
        try
        {
            searchedNumber = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        }
        finally
        {
            isLoading = false;
            searched = true;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

